  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Proyek Butuh Pengukur Jarak Tanpa Kontak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak proyek elektronik membutuhkan pengukuran jarak: robot penghindar halangan, parkir otomatis, atau tong sampah pintar. Mengukur manual dengan penggaris tidak praktis dan tidak bisa otomatis. Sensor ultrasonik HC-SR04 menyelesaikan masalah ini dengan mengukur jarak tanpa menyentuh benda, akurat hingga satuan sentimeter.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Cara Kerja HC-SR04$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$HC-SR04 bekerja seperti kelelawar. Pin Trigger mengirim pulsa ultrasonik 40 kHz, gelombang memantul dari benda, lalu pin Echo menerima pantulannya. Mikrokontroler mengukur lama perjalanan pulsa. Rumusnya: jarak = (waktu tempuh x kecepatan suara 340 m/detik) / 2. Pembagi 2 karena gelombang pergi-pulang. Jangkauan efektif sensor ini sekitar 2 cm sampai 4 meter.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sensor ultrasonik HC-SR04$txt$, $txt$Arduino Uno (atau Nano)$txt$, $txt$Kabel jumper male-to-male secukupnya$txt$, $txt$Kabel USB untuk menghubungkan ke laptop$txt$, $txt$Benda uji (buku atau kardus)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Merangkai dan Memprogram$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Hubungkan VCC HC-SR04 ke 5V Arduino, GND ke GND$txt$, $txt$Hubungkan pin Trig ke pin digital 9, pin Echo ke pin digital 10$txt$, $txt$Buka Arduino IDE, buat sketch baru$txt$, $txt$Kirim pulsa 10 mikrodetik ke pin Trig, lalu baca durasi pulsa di pin Echo dengan pulseIn$txt$, $txt$Hitung jarak dengan rumus: jarak_cm = durasi * 0.034 / 2$txt$, $txt$Tampilkan hasil ke Serial Monitor (baud 9600)$txt$, $txt$Uji dengan menggerakkan benda mendekat dan menjauh$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Permukaan penyerap suara seperti kain atau busa membuat pantulan lemah dan bacaan tidak stabil. Benda yang miring ekstrem memantulkan gelombang menjauh dari sensor. Jarak di bawah 2 cm tidak terbaca (zona buta). Jangan memberi tegangan di atas 5V ke sensor. Pastikan pin Echo tidak langsung ke pin analog tanpa pembagi tegangan bila memakai board 3,3V.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Buka Serial Monitor: angka jarak harus berubah mulus mengikuti gerakan benda dan mendekati hasil pengukuran penggaris (selisih wajar 1-2 cm). Bila angka meloncat-loncat, cek sambungan kabel dan ganti benda uji dengan permukaan keras dan rata. Tindak lanjut: gabungkan dengan buzzer agar berbunyi saat benda terlalu dekat, atau dengan servo untuk robot penghindar halangan.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Perkedel Lembek dan Hancur Saat Digoreng$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Perkedel kentang sering gagal: adonan lembek, hancur berantakan di minyak, atau hasilnya berminyak dan tidak renyah. Penyebab utamanya adalah kentang yang direbus sehingga menyerap banyak air, dan adonan yang terlalu basah. Dengan teknik yang benar, perkedel bisa renyah di luar, lembut di dalam, dan utuh saat digoreng.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Kunci Perkedel Renyah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Rahasia perkedel renyah ada tiga. Pertama, kentang digoreng (bukan direbus) lalu ditumbuk selagi panas agar teksturnya kering dan pulen. Kedua, adonan harus padat dan bisa dibentuk tanpa lengket di tangan. Ketiga, balutan telur yang tipis berfungsi sebagai lem sekaligus pelapis renyah. Minyak yang cukup panas mencegah perkedel menyerap minyak berlebih.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Bahan dan Bumbu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$500 gram kentang, kupas dan potong$txt$, $txt$2 siung bawang putih, haluskan$txt$, $txt$3 butir bawang merah, iris tipis dan goreng$txt$, $txt$1 batang daun bawang, iris halus$txt$, $txt$1/2 sendok teh merica bubuk$txt$, $txt$1 sendok teh garam (sesuaikan selera)$txt$, $txt$1 butir telur, kocok lepas untuk balutan$txt$, $txt$Minyak goreng secukupnya$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Membuat$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Goreng potongan kentang hingga matang dan kecokelatan, tiriskan$txt$, $txt$Tumbuk kentang selagi panas hingga halus$txt$, $txt$Campur dengan bawang putih halus, bawang merah goreng, daun bawang, merica, dan garam$txt$, $txt$Uleni hingga rata dan bisa dibentuk; bila terlalu lembek, tambahkan sedikit tepung terigu$txt$, $txt$Bentuk bulat pipih sesuai selera$txt$, $txt$Celupkan ke kocokan telur secara tipis dan merata$txt$, $txt$Goreng dalam minyak panas dengan api sedang hingga kuning keemasan$txt$, $txt$Tiriskan di atas tisu dapur agar minyak berlebih terserap$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Minyak kurang panas membuat perkedel menyerap minyak dan lembek. Adonan yang terlalu basah akan hancur saat digoreng; perbaiki dengan menambah tepung sedikit demi sedikit. Jangan membolak-balik perkedel terlalu sering agar tidak pecah. Gunakan api sedang agar matang merata sampai dalam tanpa gosong di luar.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Perkedel yang berhasil berwarna kuning keemasan, renyah saat digigit, lembut di dalam, dan tidak berminyak. Sajikan hangat sebagai lauk atau camilan. Sisa perkedel mentah bisa disimpan di kulkas 1-2 hari dalam wadah tertutup; goreng sesaat sebelum disajikan agar tetap renyah.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Belerang?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Belerang atau sulfur adalah unsur kimia dengan simbol S dan nomor atom 16. Dalam bentuk murni ia berupa padatan kristal berwarna kuning cerah yang rapuh. Belerang dikenal sejak zaman kuno dan namanya berasal dari bahasa Sansekerta sulvere. Unsur ini termasuk nonlogam dan sangat penting dalam kimia industri maupun biologi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat Khas yang Mudah Dikenali$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Ciri paling terkenal belerang adalah baunya. Senyawa belerang seperti hidrogen sulfida (H2S) berbau seperti telur busuk dan bisa tercium dalam konsentrasi sangat kecil. Belerang meleleh pada suhu relatif rendah sekitar 115 derajat Celsius dan mudah terbakar menghasilkan api biru serta gas sulfur dioksida yang menyengat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Belerang di Alam Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Belerang banyak ditemukan di sekitar gunung berapi aktif. Di Indonesia, Kawah Ijen di Jawa Timur terkenal dengan tambang belerang tradisionalnya, di mana penambang memikul bongkahan belerang kuning dari dasar kawah. Belerang juga terdapat dalam gas alam dan minyak bumi sebagai pengotor yang harus dipisahkan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Manfaat dalam Kehidupan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Kegunaan terbesar belerang adalah bahan baku asam sulfat, zat kimia industri yang paling banyak diproduksi di dunia untuk pupuk, baterai, dan deterjen. Belerang dipakai dalam vulkanisasi karet agar ban tidak lengket, dalam korek api, fungisida pertanian, serta salep obat penyakit kulit seperti kudis.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Bahaya dan Dampak Lingkungan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Pembakaran belerang menghasilkan sulfur dioksida (SO2), gas beracun yang mengiritasi saluran pernapasan dan menjadi penyebab hujan asam yang merusak hutan, danau, dan bangunan. Karena itu emisi industri berbelerang diatur ketat. Hidrogen sulfida dalam kadar tinggi juga berbahaya dan bisa mematikan, sehingga pekerja tambang dan kilang wajib memakai pelindung pernapasan.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu PRRI?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$PRRI adalah singkatan dari Pemerintah Revolusioner Republik Indonesia, sebuah pemerintahan tandingan yang dideklarasikan pada 15 Februari 1958 di Padang, Sumatera Barat. Gerakan ini dipimpin tokoh-tokoh sipil dan militer daerah yang kecewa terhadap pemerintah pusat di Jakarta. PRRI menjadi salah satu pemberontakan daerah terbesar pada era Demokrasi Liberal.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang: Ketidakpuasan Daerah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Akar masalahnya adalah kesenjangan antara pusat dan daerah. Daerah penghasil devisa seperti Sumatera merasa hasil buminya disedot ke Jakarta tanpa pembangunan yang seimbang. Ketidakpuasan ini melahirkan dewan-dewan daerah: Dewan Banteng di Sumatera Barat, Dewan Garuda di Sumatera Selatan, Dewan Gajah di Sumatera Utara, dan Dewan Manguni di Sulawesi Utara. Ketegangan memuncak setelah kabinet-kabinet parlementer silih berganti tanpa menyelesaikan masalah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Deklarasi 15 Februari 1958$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Setelah ultimatum kepada pemerintah pusat tidak dipenuhi, para tokoh daerah memproklamasikan PRRI di Padang. Syafruddin Prawiranegara, mantan Menteri Keuangan dan Gubernur Bank Indonesia, ditunjuk sebagai perdana menteri pemerintahan revolusioner itu. Mereka menuntut pembubaran kabinet dan pembentukan kabinet yang adil bagi daerah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Jalannya Pemberontakan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Pemerintah pusat di bawah Presiden Soekarno menolak tuntutan dan melancarkan operasi militer besar-besaran. TNI mengerahkan Operasi 17 Agustus ke Sumatera Barat, Operasi Tegas ke Riau, dan Operasi Saptamarga ke Sumatera Utara. Pasukan pusat yang lebih kuat dan terorganisir secara bertahap merebut kembali kota-kota yang dikuasai PRRI, memaksa para pemimpinnya bergerilya ke hutan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Akhir dan Pelajaran Sejarah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Perlawanan bersenjata berakhir sekitar tahun 1961 ketika para pemimpin PRRI menyerah dan menerima amnesti dari pemerintah. Peristiwa ini menjadi pelajaran penting tentang hubungan pusat dan daerah: pembangunan yang tidak merata dan komunikasi politik yang buntu bisa menyulut konflik. Pengalaman PRRI ikut mendorong gagasan otonomi daerah yang berkembang puluhan tahun kemudian.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menjelaskan pengertian evolusi makhluk hidup$txt$, $txt$Menguraikan teori evolusi Darwin dan mekanisme seleksi alam$txt$, $txt$Menyebutkan bukti-bukti evolusi$txt$, $txt$Menganalisis contoh peristiwa evolusi dalam kehidupan sehari-hari$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Evolusi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Evolusi adalah perubahan sifat makhluk hidup yang diwariskan dari generasi ke generasi dalam waktu yang sangat lama. Perubahan ini terjadi karena mutasi gen dan seleksi alam. Evolusi menjelaskan mengapa keanekaragaman hayati di Bumi begitu luar biasa, dari bakteri mikroskopis hingga paus biru raksasa, semuanya memiliki nenek moyang yang sama.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Teori Darwin dan Seleksi Alam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Charles Darwin dalam bukunya On the Origin of Species (1859) mengemukakan bahwa individu yang paling sesuai dengan lingkungannya akan bertahan hidup dan mewariskan sifatnya, sedangkan yang tidak sesuai akan punah. Proses ini disebut seleksi alam. Contoh klasiknya adalah jerapah: nenek moyang berleher pendek yang bermutasi berleher lebih panjang dapat mencapai daun di tempat tinggi sehingga bertahan dan berkembang biak.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Bukti-bukti Evolusi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Fosil: sisa makhluk hidup purba yang menunjukkan perubahan bentuk bertahap, misalnya fosil kuda$txt$, $txt$Homologi: organ dengan struktur dasar sama pada spesies berbeda, misalnya tangan manusia dan sayap kelelawar$txt$, $txt$Embriologi: embrio vertebrata yang mirip pada tahap awal perkembangan$txt$, $txt$Biokimia dan DNA: semakin dekat kekerabatan, semakin mirip urutan DNA-nya$txt$, $txt$Vestigial: organ sisa yang tidak berfungsi lagi, misalnya tulang ekor manusia$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Contoh: Ngengat Biston betularia di Inggris sebelum revolusi industri mayoritas berwarna terang. Setelah polusi menghitamkan pepohonan, ngengat berwarna gelap lebih sulit terlihat predator sehingga jumlahnya melonjak. Jelaskan dengan teori Darwin! Jawab: terjadi seleksi alam. Lingkungan berubah (pohon menghitam), ngengat gelap lebih adaptif, bertahan hidup, dan mewariskan warna gelap ke keturunannya. Inilah evolusi yang teramati dalam puluhan tahun.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Soal 1: Jelaskan perbedaan teori evolusi Darwin dan Lamarck. Kunci: Lamarck menyatakan organ yang sering dipakai berkembang dan diwariskan (use and disuse), sedangkan Darwin menyatakan seleksi alam memilih individu yang paling adaptif.$txt$, $txt$Soal 2: Sebutkan tiga bukti evolusi beserta contohnya. Kunci: fosil (fosil kuda), homologi (tangan manusia-sayap kelelawar), DNA (kemiripan urutan DNA manusia-simpanse sekitar 98 persen).$txt$, $txt$Soal 3: Mengapa bakteri menjadi resisten terhadap antibiotik? Kunci: karena seleksi alam; bakteri yang kebal bertahan dan berkembang biak, sedangkan yang tidak kebal mati.$txt$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menyebutkan lima rukun Islam dengan benar$txt$, $txt$Menghafal urutan rukun Islam$txt$, $txt$Menyebutkan contoh pengamalan rukun Islam dalam kehidupan sehari-hari$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Rukun Islam?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Anak-anak, rukun Islam adalah lima perbuatan pokok yang wajib dilakukan oleh setiap muslim. Kata rukun artinya tiang atau dasar. Seperti rumah yang berdiri kokoh karena tiangnya kuat, keislaman seseorang menjadi kokoh bila ia menjalankan lima rukun Islam. Mari kita kenali satu per satu dengan gembira!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Lima Rukun Islam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Rukun pertama: mengucapkan dua kalimat syahadat$txt$, $txt$Rukun kedua: mendirikan salat lima waktu$txt$, $txt$Rukun ketiga: membayar zakat$txt$, $txt$Rukun keempat: berpuasa pada bulan Ramadan$txt$, $txt$Rukun kelima: menunaikan ibadah haji bagi yang mampu$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh dalam Kehidupan Sehari-hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Kita mengamalkan rukun Islam setiap hari. Saat mengaji kita mengucap syahadat, saat azan berkumandang kita bersiap salat, saat Ramadan kita ikut sahur dan berbuka bersama keluarga, dan kita belajar berbagi kepada teman yang membutuhkan sebagai latihan berzakat. Ibadah haji kita doakan agar kelak bisa menunaikannya bersama orang tua.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Mari Menghafal dengan Lagu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Agar mudah hafal, nyanyikan urutannya dengan nada ceria: syahadat, salat, zakat, puasa, haji, itulah rukun Islam yang lima! Ulangi tiga kali sambil bertepuk tangan. Ajak ayah, bunda, atau teman untuk menghafal bersama agar semakin semangat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Soal 1: Ada berapa rukun Islam? Kunci: lima.$txt$, $txt$Soal 2: Sebutkan rukun Islam yang pertama! Kunci: mengucapkan dua kalimat syahadat.$txt$, $txt$Soal 3: Pada bulan apa umat Islam berpuasa? Kunci: bulan Ramadan.$txt$])));
